import * as React from "react";
import { render, screen } from "@testing-library/react";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import ConsoleSpy from "../../lib/tests/ConsoleSpy";
import Link from "../Link";
import * as stories from "./Breadcrumb.stories";
import Breadcrumb, { BreadcrumbItem } from ".";

const { Basic } = composeStories(stories) as any;

describe("Breadcrumb component", () => {
  let consoleSpy = ConsoleSpy();

  it("pass A11Y", async () => {
    const { container } = render(<Basic />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("display warnings with invalid props", () => {
    const { rerender } = render(
      <Breadcrumb>
        <>fragment</>
      </Breadcrumb>
    );
    expect(consoleSpy.warn).toHaveBeenCalledTimes(1);
    expect(consoleSpy.warn.mock.calls[0][0]).toMatch(
      /Breadcrumb component doesn't accept a Fragment as a child/
    );

    rerender(
      <Breadcrumb>
        <div>test</div>
        <Link>Home</Link>
      </Breadcrumb>
    );
    expect(consoleSpy.warn).toHaveBeenCalledTimes(3);
    expect(consoleSpy.warn.mock.calls[2][0]).toMatch(
      /Breadcrumb component only accept BreadcrumbItem/
    );
  });

  it("passes through props", () => {
    render(
      <Breadcrumb data-testid="breadcrumb">
        <BreadcrumbItem data-testid="breadcrumbitem"></BreadcrumbItem>
      </Breadcrumb>
    );
    expect(screen.getByTestId("breadcrumb")).toBeTruthy();
    expect(screen.getByTestId("breadcrumbitem")).toBeTruthy();
  });
});
